section.code:
from _afwdev.test.c_probe import run_c_probe

def run():
    return run_c_probe(
        "pool_alloc_probe.c",
        "Pool malloc rejects a wrapping size",
        [
            ("overflow", "pool malloc of SIZE_MAX throws memory"),
            ("overflow-subpool", "subpool malloc of SIZE_MAX throws memory"),
        ],
    )

#!/usr/bin/env -S afw --syntax test_script
//? testScript: example.as
//? description: What this file covers
//? sourceType: script
//?
//? test: case-1
//? description: short case title
//? expect: true
//? source: ...

return true;

//?
//? test: case-2
//? description: another case
//? expect: 0
//? source: ...

// body …
return 0;

section.paragraph:
Same-line values, for instance 
//? expect: 0 or 
//? description: short title, have leading 
and trailing whitespace ignored.
